// ---- Full Throttle Original Citrus
const n2 = (v) => Math.round(v * 100) / 100, n1 = (v) => Math.round(v * 10) / 10;
// One feather: a pointed leaf from (x,y) along angle a (degrees): base tone and shadow half per feather;
// the dark midribs and highlight lines of a whole fan are collected into one path each.
function feather(x, y, a, len, w, [base, dark], ribs) {
  const c = Math.cos(a * Math.PI / 180), s = Math.sin(a * Math.PI / 180);
  const P = (t, k) => `${n1(x + c * len * t - s * w * k)} ${n1(y + s * len * t + c * w * k)}`;
  ribs.mid += `M${P(.1, 0)}Q${P(.55, .12)} ${P(.95, 0)}`;
  ribs.hi += `M${P(.15, .45)}Q${P(.55, .65)} ${P(.85, .25)}`;
  return `<path d="M${P(0, 0)}Q${P(.55, 1.3)} ${P(1, 0)}Q${P(.55, -1.3)} ${P(0, 0)}Z" fill="${base}" stroke="#0c0c0d" stroke-width=".7"/>`
    + `<path d="M${P(0, 0)}Q${P(.55, -1.25)} ${P(1, 0)}Q${P(.55, -.1)} ${P(0, 0)}Z" fill="${dark}"/>`;
}
const FEATHER_BACK = ['#a9adb2', '#6f7378', '#d7dadd'], FEATHER_FRONT = ['#d3d6d9', '#8f9398', '#fbfbfb'];
const ribPaths = (ribs, tones) => `<path d="${ribs.mid}" fill="none" stroke="#4d5156" stroke-width=".7"/><path d="${ribs.hi}" fill="none" stroke="${tones[2]}" stroke-width=".6" stroke-linecap="round"/>`;
// A fan of feathers from one point (the lower chest and tail fan).
function fan(x, y, a0, a1, step, len, w, tones) {
  let o = ''; const ribs = { mid: '', hi: '' };
  for (let a = a0; a <= a1 + .01; a += step) {
    const mid = (a0 + a1) / 2, k = 1 - Math.abs(a - mid) / ((a1 - a0) / 2 + 1);
    o += feather(x, y, a, len * (.8 + .2 * k), w, tones, ribs);
  }
  return o + ribPaths(ribs, tones);
}
// An upright wing on one can edge: feathers stacked up the edge, pointing up and slightly outward (side -1 left, 1 right).
function wing(side, x0, y0, n, len, w, tones, shift = 0) {
  let o = ''; const ribs = { mid: '', hi: '' };
  for (let i = n - 1; i >= 0; i--) {
    const j = i + shift;
    o += feather(100 + side * (x0 - j * 2.2), y0 - j * 2.6, 270 + side * (10 - j * 1.4), len - j * 6.5, w, tones, ribs);
  }
  return o + ribPaths(ribs, tones);
}
const star = (cx, cy, r) => {
  let lit = '', dim = '';
  for (let i = 0; i < 5; i++) {
    const a = -90 + i * 72, p = (ang, rr) => `${n2(cx + rr * Math.cos(ang * Math.PI / 180))} ${n2(cy + rr * Math.sin(ang * Math.PI / 180))}`;
    lit += `M${cx} ${cy}L${p(a, r)}L${p(a - 36, r * .4)}Z`;
    dim += `M${cx} ${cy}L${p(a, r)}L${p(a + 36, r * .4)}Z`;
  }
  return `<path d="${lit}" fill="#f4f5f6"/><path d="${dim}" fill="#a6abb3"/>`;
};
